create extension if not exists pgcrypto;
create type public.project_status as enum ('active','paused','completed');
create type public.employee_status as enum ('active','inactive');
create type public.entry_source as enum ('web','telegram');
create table public.profiles (id uuid primary key references auth.users(id) on delete cascade, full_name text, role text not null default 'manager' check (role in ('admin','manager')), created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create table public.projects (id uuid primary key default gen_random_uuid(), name text not null check (char_length(name) between 1 and 160), description text, location text, status public.project_status not null default 'active', start_date date, end_date date, notes text, created_at timestamptz not null default now(), updated_at timestamptz not null default now(), constraint project_dates_valid check (end_date is null or start_date is null or end_date >= start_date));
create table public.employees (id uuid primary key default gen_random_uuid(), first_name text not null, last_name text not null, phone text, employee_number text not null unique, status public.employee_status not null default 'active', notes text, created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create table public.time_entries (id uuid primary key default gen_random_uuid(), work_date date not null, employee_id uuid not null references public.employees(id) on delete restrict, project_id uuid not null references public.projects(id) on delete restrict, regular_hours numeric(5,2) not null default 0 check (regular_hours >= 0 and regular_hours <= 24), overtime_hours numeric(5,2) not null default 0 check (overtime_hours >= 0 and overtime_hours <= 24), notes text, source public.entry_source not null default 'web', created_by uuid not null default auth.uid() references auth.users(id) on delete restrict, created_at timestamptz not null default now(), updated_at timestamptz not null default now(), constraint positive_hours check (regular_hours + overtime_hours > 0 and regular_hours + overtime_hours <= 24), constraint unique_daily_entry unique(employee_id,project_id,work_date));
create index projects_status_idx on public.projects(status); create index employees_status_idx on public.employees(status); create index employees_name_idx on public.employees(last_name,first_name); create index time_entries_date_idx on public.time_entries(work_date desc); create index time_entries_project_date_idx on public.time_entries(project_id,work_date desc); create index time_entries_employee_date_idx on public.time_entries(employee_id,work_date desc);
create or replace function public.set_updated_at() returns trigger language plpgsql security invoker set search_path = '' as $$ begin new.updated_at = now(); return new; end; $$;
create trigger profiles_updated_at before update on public.profiles for each row execute function public.set_updated_at(); create trigger projects_updated_at before update on public.projects for each row execute function public.set_updated_at(); create trigger employees_updated_at before update on public.employees for each row execute function public.set_updated_at(); create trigger time_entries_updated_at before update on public.time_entries for each row execute function public.set_updated_at();
create or replace function public.handle_new_user() returns trigger language plpgsql security definer set search_path = '' as $$ begin insert into public.profiles(id,full_name) values(new.id,new.raw_user_meta_data->>'full_name'); return new; end; $$;
create trigger on_auth_user_created after insert on auth.users for each row execute function public.handle_new_user();
alter table public.profiles enable row level security; alter table public.projects enable row level security; alter table public.employees enable row level security; alter table public.time_entries enable row level security;
create policy "authenticated read profiles" on public.profiles for select to authenticated using (true); create policy "users update own profile" on public.profiles for update to authenticated using (id=auth.uid()) with check (id=auth.uid()); create policy "authenticated manage projects" on public.projects for all to authenticated using (true) with check (true); create policy "authenticated manage employees" on public.employees for all to authenticated using (true) with check (true); create policy "authenticated manage entries" on public.time_entries for all to authenticated using (true) with check (true);
